# -*- coding: utf-8 -*-
"""
光明积木 — 领域专属补充块生成器
=================================
为全部 45 个领域生成 ~130-150 个真正领域专属的积木块，
无泛化噪声（无"各元素"、"成对"、"滚动"、"乘积"等通用操作）。

用法：
    python 领域补充.py

输出：
    - 积木库_导出_v4.json  (合并更新)
    - blocks_v4/{领域}/{导出名}.light  (单个文件)
"""

import os, json, hashlib

_HERE = os.path.abspath(os.path.dirname(__file__))

# ============================================================
# 辅助函数 — 生成 .light 源码
# ============================================================

def _块(领域, 名称, 导出名, 描述, 输入类型, 输出类型, 变换):
    """单输入变换块"""
    源码 = f"""# 积木：{名称}（{领域}领域，自动生成）
# 契约：输入 [{输入类型}] → 输出 {输出类型}（{描述}）
导出 {导出名}
段落 {导出名} 接收 输入：
    返回 {变换}
"""
    return {
        '名称': 名称, '领域': 领域, '导出名': 导出名, '描述': 描述,
        '输入': [{'名': '输入', '类型': 输入类型}],
        '输出': {'类型': 输出类型}, '稳定性': 'generated', '源码': 源码,
    }


def _双(领域, 名称, 导出名, 描述, 输入类型, 输出类型, 操作):
    """双输入运算块"""
    源码 = f"""# 积木：{名称}（{领域}领域，自动生成）
# 契约：输入 [{输入类型}, {输入类型}] → 输出 {输出类型}（{描述}）
导出 {导出名}
段落 {导出名} 接收 甲, 乙：
    返回 甲 {操作} 乙
"""
    return {
        '名称': 名称, '领域': 领域, '导出名': 导出名, '描述': 描述,
        '输入': [{'名': '甲', '类型': 输入类型}, {'名': '乙', '类型': 输入类型}],
        '输出': {'类型': 输出类型}, '稳定性': 'generated', '源码': 源码,
    }


def _三(领域, 名称, 导出名, 描述, 输入类型, 输出类型, 变换):
    """三输入变换块"""
    源码 = f"""# 积木：{名称}（{领域}领域，自动生成）
# 契约：输入 [{输入类型}, {输入类型}, {输入类型}] → 输出 {输出类型}（{描述}）
导出 {导出名}
段落 {导出名} 接收 甲, 乙, 丙：
    返回 {变换}
"""
    return {
        '名称': 名称, '领域': 领域, '导出名': 导出名, '描述': 描述,
        '输入': [{'名': '甲', '类型': 输入类型}, {'名': '乙', '类型': 输入类型}, {'名': '丙', '类型': 输入类型}],
        '输出': {'类型': 输出类型}, '稳定性': 'generated', '源码': 源码,
    }


def _字串(领域, 名称, 导出名, 描述, 输出类型, 操作):
    """字符串操作块"""
    源码 = f"""# 积木：{名称}（{领域}领域，自动生成）
# 契约：输入 [文本] → 输出 {输出类型}（{描述}）
导出 {导出名}
段落 {导出名} 接收 文本：
    返回 {操作}
"""
    return {
        '名称': 名称, '领域': 领域, '导出名': 导出名, '描述': 描述,
        '输入': [{'名': '文本', '类型': '文本'}],
        '输出': {'类型': 输出类型}, '稳定性': 'generated', '源码': 源码,
    }


def _聚集(领域, 名称, 导出名, 描述, 输出类型, 初始值, 操作符):
    """列表聚合块"""
    源码 = f"""# 积木：{名称}（{领域}领域，自动生成）
# 契约：输入 [列表] → 输出 {输出类型}（{描述}）
导出 {导出名}
段落 {导出名} 接收 列表：
    设 结果 为 {初始值}
    设 i 为 0
    当 i 小于 长度(列表)：
        设 结果 为 {操作符}
        设 i 为 i 加 1
    返回 结果
"""
    return {
        '名称': 名称, '领域': 领域, '导出名': 导出名, '描述': 描述,
        '输入': [{'名': '列表', '类型': '列表'}],
        '输出': {'类型': 输出类型}, '稳定性': 'generated', '源码': 源码,
    }


def _条件(领域, 名称, 导出名, 描述, 输出类型, 条件, 真值, 假值):
    """条件选择块"""
    源码 = f"""# 积木：{名称}（{领域}领域，自动生成）
# 契约：输入 [数] → 输出 {输出类型}（{描述}）
导出 {导出名}
段落 {导出名} 接收 输入：
    如果 {条件}：
        返回 {真值}
    否则：
        返回 {假值}
"""
    return {
        '名称': 名称, '领域': 领域, '导出名': 导出名, '描述': 描述,
        '输入': [{'名': '输入', '类型': '数'}],
        '输出': {'类型': 输出类型}, '稳定性': 'generated', '源码': 源码,
    }


